// Batch 11 — Royalty & Dynasties. Source of src/content/batches/batch-11.json (run: node docs/content-research/batch-11.src.cjs).
// Every fact in a story comes from a quoted source sentence; clues and hints are general geography.
const B = "https://www.britannica.com/";
const entries = [];
const P = (id, name, mono, cc, region, sub, q) => entries.push({
 entity: { id, name, monogram: mono, countryOfOrigin: cc, region, ...(q.originNote ? { originNote: q.originNote } : {}) },
 question: { id: q.qid, primaryCategory: "royalty", subcategory: sub, questionType: q.type, difficulty: q.diff, displayCategory: q.display, chapter: q.chapter,
  question: q.question, clue: q.clue, hint: q.hint, answer: { city: q.city, country: q.country, countryCode: q.code, ...(q.geocode ? { geocode: q.geocode } : {}) }, story: q.story,
  sources: q.quotes.map((quote, i) => ({ url: B + q.url, role: i ? "extra" : "primary", quality: "reputable_secondary", quote })) },
});

